package in.asmj.ride.web;
import in.asmj.ride.model.*;import in.asmj.ride.repo.*;import in.asmj.ride.service.FareCalculator;
import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.Authentication;import org.springframework.http.ResponseEntity;
import java.time.*;import java.util.*;import java.security.SecureRandom;
import org.springframework.beans.factory.annotation.Value;
@Controller
public class RideController {
 private final UserAccountRepository users; private final RideBookingRepository rides; private final VehicleRepository vehicles; private final FareRuleRepository fareRules; private final FareCalculator fareCalculator; private final SecureRandom random=new SecureRandom();
 public RideController(UserAccountRepository u,RideBookingRepository r,VehicleRepository v,FareRuleRepository f,FareCalculator c){users=u;rides=r;vehicles=v;fareRules=f;fareCalculator=c;}
 private UserAccount me(Authentication a){return users.findByEmailIgnoreCase(a.getName()).orElseThrow();}
 private FareRule fare(){return fareRules.findById("default").orElseGet(()->fareRules.save(new FareRule()));}
 @GetMapping("/customer") String customer(Authentication a,Model m){UserAccount u=me(a);m.addAttribute("name",u.getName());m.addAttribute("rides",rides.findByCustomerIdOrderByCreatedAtDesc(u.getId()));m.addAttribute("fareRule",fare());return "customer";}
 @PostMapping("/rides/book") String book(Authentication a,@RequestParam String pickup,@RequestParam String destination,@RequestParam String category,@RequestParam String tripType,@RequestParam(required=false) String scheduledAt,@RequestParam String paymentMethod,@RequestParam(required=false,defaultValue="0") double distanceKm){
  UserAccount u=me(a);if(pickup.isBlank()||destination.isBlank()||pickup.length()>250||destination.length()>250||pickup.trim().equalsIgnoreCase(destination.trim()))return "redirect:/customer?error=locations";
  if(!List.of("CAR","AUTO","BIKE","OTHER").contains(category)||!List.of("IMMEDIATE","SCHEDULED").contains(tripType)||!List.of("CASH","UPI").contains(paymentMethod)||distanceKm<0||distanceKm>500)return "redirect:/customer?error=details";
  RideBooking r=new RideBooking();r.setCustomerId(u.getId());r.setCustomerName(u.getName());r.setCustomerMobile(u.getMobile());r.setPickup(pickup.trim());r.setDestination(destination.trim());r.setCategory(category);r.setTripType(tripType);r.setPaymentMethod(paymentMethod);r.setEstimatedDistanceKm(distanceKm);r.setEstimatedFare(fareCalculator.estimate(fare(),category,distanceKm));
  if("SCHEDULED".equals(tripType)){try{LocalDateTime dt=LocalDateTime.parse(scheduledAt);if(dt.isBefore(LocalDateTime.now().plusMinutes(30))||dt.isAfter(LocalDateTime.now().plusDays(30)))return "redirect:/customer?error=schedule";r.setScheduledAt(dt);}catch(Exception ex){return "redirect:/customer?error=schedule";}}
  r.setStatus("REQUESTED");rides.save(r);return "redirect:/customer?booked";
 }
 @GetMapping("/driver") String driver(Authentication a,Model m){UserAccount u=me(a);m.addAttribute("name",u.getName());m.addAttribute("available",u.isAvailable());m.addAttribute("rides",rides.findByStatusInOrderByCreatedAtDesc(List.of("REQUESTED","ACCEPTED","ASSIGNED","IN_PROGRESS")));m.addAttribute("myRides",rides.findByAssignedDriverIdOrderByCreatedAtDesc(u.getId()));m.addAttribute("vehicles",eligibleVehicles(u));return "driver";}
 private List<Vehicle> eligibleVehicles(UserAccount u){List<Vehicle> out=new ArrayList<>();for(Vehicle v:vehicles.findByStatus("APPROVED"))if(u.getId().equals(v.getOwnerId())||u.getId().equals(v.getAssignedDriverId()))out.add(v);return out;}
 @PostMapping("/driver/availability") String availability(Authentication a,@RequestParam boolean available){UserAccount u=me(a);u.setAvailable(available);users.save(u);return "redirect:/driver";}
 @PostMapping("/rides/{id}/accept") String accept(Authentication a,@PathVariable String id,@RequestParam String vehicleId){UserAccount u=me(a);if(!u.isAvailable()||!u.isMobileVerified()||!"APPROVED".equals(u.getStatus()))return "redirect:/driver?error=unavailable";if(rides.findByAssignedDriverIdOrderByCreatedAtDesc(u.getId()).stream().anyMatch(x->List.of("ACCEPTED","IN_PROGRESS").contains(x.getStatus())))return "redirect:/driver?error=active";
  RideBooking r=rides.findById(id).orElseThrow();if(!"REQUESTED".equals(r.getStatus()))return "redirect:/driver?error=taken";Vehicle v=eligibleVehicles(u).stream().filter(x->x.getId().equals(vehicleId)&&x.getCategory().equals(r.getCategory())).findFirst().orElse(null);if(v==null)return "redirect:/driver?error=vehicle";
  r.setAssignedDriverId(u.getId());r.setAssignedDriverName(u.getName());r.setAssignedVehicleId(v.getId());r.setAssignedVehicleNumber(v.getRegistrationNumber());r.setPickupOtp(String.format("%06d",random.nextInt(1_000_000)));r.setStatus("ACCEPTED");rides.save(r);return "redirect:/driver?accepted";
 }
 @PostMapping("/rides/{id}/status") String updateStatus(Authentication a,@PathVariable String id,@RequestParam String status,@RequestParam(required=false) String pickupOtp,@RequestParam(required=false,defaultValue="0") double actualDistanceKm,@RequestParam(required=false,defaultValue="0") int actualDurationMinutes,@RequestParam(required=false,defaultValue="0") int waitingMinutes){UserAccount u=me(a);RideBooking r=rides.findById(id).orElseThrow();if(!u.getId().equals(r.getAssignedDriverId()))return "redirect:/driver?error=denied";
  if("IN_PROGRESS".equals(status)){if(!"ACCEPTED".equals(r.getStatus())||pickupOtp==null||!pickupOtp.equals(r.getPickupOtp()))return "redirect:/driver?error=otp";r.setTripStartedAt(Instant.now());r.setStatus("IN_PROGRESS");}
  else if("COMPLETED".equals(status)){if(!"IN_PROGRESS".equals(r.getStatus())||actualDistanceKm<0||actualDistanceKm>500||actualDurationMinutes<0||actualDurationMinutes>1440||waitingMinutes<0||waitingMinutes>1440)return "redirect:/driver?error=tripdata";r.setActualDistanceKm(actualDistanceKm);r.setActualDurationMinutes(actualDurationMinutes);r.setWaitingMinutes(waitingMinutes);r.setFinalFare(fareCalculator.finalFare(fare(),r.getCategory(),actualDistanceKm,actualDurationMinutes,waitingMinutes,r.getTripStartedAt()==null?null:LocalDateTime.ofInstant(r.getTripStartedAt(),ZoneId.systemDefault())));r.setTripCompletedAt(Instant.now());r.setPickupOtp(null);r.setStatus("COMPLETED");}
  else return "redirect:/driver";rides.save(r);return "redirect:/driver?updated";
 }
 @PostMapping("/driver/location") String location(Authentication a,@RequestParam double latitude,@RequestParam double longitude){UserAccount u=me(a);if(latitude < -90||latitude>90||longitude < -180||longitude>180)return "redirect:/driver?error=location";for(RideBooking r:rides.findByAssignedDriverIdOrderByCreatedAtDesc(u.getId()))if("IN_PROGRESS".equals(r.getStatus())||"ACCEPTED".equals(r.getStatus())){r.setCurrentDriverLatitude(latitude);r.setCurrentDriverLongitude(longitude);r.setDriverLocationUpdatedAt(Instant.now());rides.save(r);}return "redirect:/driver?location=updated";}
 @GetMapping("/rides/{id}/location") @ResponseBody ResponseEntity<Map<String,Object>> locationForCustomer(Authentication a,@PathVariable String id){UserAccount u=me(a);RideBooking r=rides.findById(id).orElseThrow();if(!u.getId().equals(r.getCustomerId()))return ResponseEntity.status(403).build();Map<String,Object> data=new LinkedHashMap<>();data.put("status",r.getStatus());data.put("latitude",r.getCurrentDriverLatitude());data.put("longitude",r.getCurrentDriverLongitude());data.put("updatedAt",r.getDriverLocationUpdatedAt());data.put("driver",r.getAssignedDriverName());return ResponseEntity.ok(data);}
 @GetMapping("/admin/rides") String adminRides(Model m){m.addAttribute("rides",rides.findAll());return "admin-rides";}
 @PostMapping("/admin/rides/{id}/cancel") String cancel(@PathVariable String id){RideBooking r=rides.findById(id).orElseThrow();if(!List.of("COMPLETED","CANCELLED").contains(r.getStatus())){if(List.of("ACCEPTED","IN_PROGRESS").contains(r.getStatus()))r.setCancellationCharge(fare().getCancellationFee());r.setStatus("CANCELLED");rides.save(r);}return "redirect:/admin/rides";}
 @PostMapping("/rides/{id}/cancel") String customerCancel(Authentication a,@PathVariable String id){UserAccount u=me(a);RideBooking r=rides.findById(id).orElseThrow();if(u.getId().equals(r.getCustomerId())&&List.of("REQUESTED","ACCEPTED").contains(r.getStatus())){if("ACCEPTED".equals(r.getStatus()))r.setCancellationCharge(fare().getCancellationFee());r.setPickupOtp(null);r.setStatus("CANCELLED");rides.save(r);}return "redirect:/customer";}
 @GetMapping("/admin/fares") String fareSettings(Model m){m.addAttribute("fare",fare());return "admin-fares";}
 @PostMapping("/admin/fares") String saveFares(@RequestParam double baseFare,@RequestParam double perKm,@RequestParam double perMinute,@RequestParam double minimumFare,@RequestParam double waitingPerMinute,@RequestParam double nightMultiplier,@RequestParam int nightStartHour,@RequestParam int nightEndHour,@RequestParam double cancellationFee,@RequestParam double carMultiplier,@RequestParam double autoMultiplier,@RequestParam double bikeMultiplier,@RequestParam double otherMultiplier,@RequestParam(defaultValue="15") double individualCommissionPercent,@RequestParam(defaultValue="10") double fleetCommissionPercent){if(baseFare<0||baseFare>10000||perKm<0||perKm>1000||perMinute<0||perMinute>500||minimumFare<0||minimumFare>10000||waitingPerMinute<0||waitingPerMinute>500||nightMultiplier<1||nightMultiplier>5||nightStartHour<0||nightStartHour>23||nightEndHour<0||nightEndHour>23||cancellationFee<0||cancellationFee>5000||!validMultiplier(carMultiplier)||!validMultiplier(autoMultiplier)||!validMultiplier(bikeMultiplier)||!validMultiplier(otherMultiplier)||individualCommissionPercent<0||individualCommissionPercent>50||fleetCommissionPercent<0||fleetCommissionPercent>50)return "redirect:/admin/fares?error=values";FareRule f=fare();f.setBaseFare(baseFare);f.setPerKm(perKm);f.setPerMinute(perMinute);f.setMinimumFare(minimumFare);f.setWaitingPerMinute(waitingPerMinute);f.setNightMultiplier(nightMultiplier);f.setNightStartHour(nightStartHour);f.setNightEndHour(nightEndHour);f.setCancellationFee(cancellationFee);f.setCarMultiplier(carMultiplier);f.setAutoMultiplier(autoMultiplier);f.setBikeMultiplier(bikeMultiplier);f.setOtherMultiplier(otherMultiplier);f.setIndividualCommissionPercent(individualCommissionPercent);f.setFleetCommissionPercent(fleetCommissionPercent);f.touch();fareRules.save(f);return "redirect:/admin/fares?saved";}
 private boolean validMultiplier(double v){return v>=0.1&&v<=5;}
}
